using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class TripoGalaFinalAudit{public static void Run(){const string folder="Assets/LighFight/Art/Drafts/TripoGalaPlayable";var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(folder+"/GalaHumanoidCandidate.prefab");var skin=prefab.GetComponentInChildren<SkinnedMeshRenderer>();var m=skin.sharedMesh;var lines=new List<string>{"vertices="+m.vertexCount,"triangles="+m.triangles.Length/3,"bones="+skin.bones.Length,"meshHash="+TripoGalaFullSourcePrepare.MeshHash(m)};using(var counts=m.GetBonesPerVertex())using(var weights=m.GetAllBoneWeights()){int offset=0,zero=0;float sumError=0;for(int i=0;i<counts.Length;i++){float sum=0;for(int j=0;j<counts[i];j++){var w=weights[offset+j];if(w.boneIndex<0||w.boneIndex>=skin.bones.Length||w.weight<0)throw new Exception("Invalid influence "+i);sum+=w.weight;}if(counts[i]==0)zero++;sumError=Mathf.Max(sumError,Mathf.Abs(1-sum));offset+=counts[i];}lines.Add("maxInfluences="+counts.Max());lines.Add("records="+weights.Length);lines.Add("zeroWeightedVertices="+zero);lines.Add("maxWeightSumError="+sumError.ToString("R"));if(zero!=0||sumError>.0001f)throw new Exception("Invalid skin normalization");}var ground=prefab.GetComponent<CandidateFootGrounding>();var overlay=prefab.GetComponent<NativeSupportOverlay>();lines.Add("groundBaseCap="+ground.maxCorrection);lines.Add("originalFootPoints="+overlay.supportPoints.Length);lines.Add("originalDefeatBodyPoints="+overlay.defeatBodyPoints.Length);lines.Add("originalNativeEntries="+overlay.entries.Length);File.WriteAllLines("GalaEvidence/final-data.txt",lines);Debug.Log("AGENT_RESULT Gala final exact mesh/influences checked");}}
